/**
 * @title Project overview
 * @description One project at a glance: owner and team, overall progress, milestones as a stepper, workload per person, and recent activity.
 * @route /projects/[id]
 * @height 960
 */
import { SidebarInset, SidebarProvider } from "@/components/ui/sidebar";
import { Button } from "@/components/ui/button";
import { Badge } from "@/components/ui/feedback";
import { DashboardSidebar } from "@/components/dashboard-sidebar";
import { SiteHeader } from "@/components/site-header";
import { ProjectSummary } from "@/components/project-summary";
import { Milestones } from "@/components/milestones";
import { Activity } from "@/components/activity";

export default function Page() {
  return (
    <SidebarProvider>
      <DashboardSidebar current="Projects" />
      <SidebarInset>
        <SiteHeader crumbs={[{ label: "Projects", href: "#" }, { label: "Website redesign" }]} actions={<><Button size="sm" variant="secondary" leadingIcon="share">Share</Button><Button size="sm" leadingIcon="plus">New task</Button></>} />
        <div className="flex flex-1 flex-col gap-6 p-4 md:p-6">
          <div className="flex flex-col gap-2">
            <div className="flex flex-wrap items-center gap-2"><h1 className="text-heading-h2">Website redesign</h1><Badge tone="success">On track</Badge></div>
            <p className="max-w-[72ch] text-body-medium text-fg-secondary">New marketing site on the DX design system: content model, page templates and a launch in March.</p>
          </div>
          <ProjectSummary />
          <div className="grid gap-4 lg:grid-cols-5">
            <Milestones />
            <Activity />
          </div>
        </div>
      </SidebarInset>
    </SidebarProvider>
  );
}

"use client";
import { BarChart3, Camera, Database, FileText, FolderKanban, Gauge, HelpCircle, LayoutDashboard, ListChecks, Search, Settings, Users } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import {
  Sidebar, SidebarContent, SidebarFooter, SidebarGroup, SidebarGroupLabel, SidebarHeader, SidebarMenu, SidebarMenuButton,
  SidebarMenuItem, SidebarRail,
} from "@/components/ui/sidebar";
import { BrandHeader } from "@/components/brand-header";
import { NavSecondary } from "@/components/nav-secondary";
import { NavUser } from "@/components/nav-user";

const main = [
  { title: "Dashboard", icon: LayoutDashboard }, { title: "Lifecycle", icon: ListChecks }, { title: "Analytics", icon: BarChart3 },
  { title: "Projects", icon: FolderKanban }, { title: "Team", icon: Users },
];
const documents = [{ title: "Data library", icon: Database }, { title: "Reports", icon: FileText }, { title: "Capture", icon: Camera }];
const secondary = [{ title: "Settings", url: "#", icon: Settings }, { title: "Get help", url: "#", icon: HelpCircle }, { title: "Search", url: "#", icon: Search }];

/** The app sidebar the dashboard, settings and table blocks share. Pass the current page's title. */
export function DashboardSidebar({ current = "Dashboard", variant = "inset" }: { current?: string; variant?: "sidebar" | "inset" }) {
  return (
    <Sidebar collapsible="icon" variant={variant} label="Main navigation">
      <SidebarHeader>
        <BrandHeader name="Acme Inc" detail="Workspace" logo={Gauge} />
      </SidebarHeader>
      <SidebarContent>
        <nav aria-label="Main" className="contents">
          <SidebarGroup>
            <SidebarMenu>
              {main.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <SidebarGroup>
            <SidebarGroupLabel as="h2">Documents</SidebarGroupLabel>
            <SidebarMenu>
              {documents.map((m) => (
                <SidebarMenuItem key={m.title}>
                  <SidebarMenuButton href="#" isActive={m.title === current} tooltip={m.title}><Icon name={m.icon} /><span>{m.title}</span></SidebarMenuButton>
                </SidebarMenuItem>
              ))}
            </SidebarMenu>
          </SidebarGroup>
          <NavSecondary items={secondary.map((s) => ({ ...s }))} className="mt-auto" />
        </nav>
      </SidebarContent>
      <SidebarFooter>
        <NavUser user={{ name: "Jane Cooper", email: "jane@acme.com" }} />
      </SidebarFooter>
      <SidebarRail />
    </Sidebar>
  );
}

"use client";
import { GalleryVerticalEnd, type LucideIcon } from "lucide-react";
import { Icon } from "@/components/ui/icon";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Logo, product name and a second line (plan or version) at the top of the sidebar. Links home. */
export function BrandHeader({ name = "Acme Docs", detail = "v4.0.0", logo = GalleryVerticalEnd }: { name?: string; detail?: string; logo?: LucideIcon }) {
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <SidebarMenuButton href="#" size="lg" tooltip={name}>
          <span className="grid size-8 shrink-0 place-items-center rounded-control bg-brand text-fg-on-brand"><Icon name={logo} size={16} /></span>
          <span className="flex min-w-0 flex-1 flex-col">
            <span className="truncate text-label-medium text-fg-primary">{name}</span>
            <span className="truncate text-caption-default">{detail}</span>
          </span>
        </SidebarMenuButton>
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { LucideIcon } from "lucide-react";
import type { HTMLAttributes } from "react";
import { Icon } from "@/components/ui/icon";
import { SidebarGroup, SidebarGroupContent, SidebarMenu, SidebarMenuButton, SidebarMenuItem } from "@/components/ui/sidebar";

/** Small links near the bottom of the sidebar (support, feedback). */
export function NavSecondary({ items, ...rest }: HTMLAttributes<HTMLDivElement> & { items: { title: string; url: string; icon: LucideIcon }[] }) {
  return (
    <SidebarGroup {...rest}>
      <SidebarGroupContent>
        <SidebarMenu>
          {items.map((item) => (
            <SidebarMenuItem key={item.title}>
              <SidebarMenuButton href={item.url} size="sm" tooltip={item.title}>
                <Icon name={item.icon} size={16} />
                <span>{item.title}</span>
              </SidebarMenuButton>
            </SidebarMenuItem>
          ))}
        </SidebarMenu>
      </SidebarGroupContent>
    </SidebarGroup>
  );
}

"use client";
import { ChevronsUpDown } from "lucide-react";
import { Avatar } from "@/components/ui/display";
import { Icon } from "@/components/ui/icon";
import { Menu } from "@/components/ui/overlays";
import { SidebarMenu, SidebarMenuButton, SidebarMenuItem, useSidebar } from "@/components/ui/sidebar";

/** The signed-in person at the bottom of the sidebar, with an account menu. */
export function NavUser({ user }: { user: { name: string; email: string } }) {
  const { isMobile, state } = useSidebar();
  return (
    <SidebarMenu>
      <SidebarMenuItem>
        <Menu
          label={`Account menu for ${user.name}`}
          className="flex w-full"
          placement={!isMobile && state === "collapsed" ? "right-end" : "top-start"}
          items={[
            { label: "Profile", icon: "user" },
            { label: "Billing", icon: "credit-card" },
            { label: "Notifications", icon: "bell" },
            { label: "Sign out", icon: "sign-out", separatorBefore: true },
          ]}
          trigger={({ ref, ...p }) => (
            <SidebarMenuButton ref={ref as React.Ref<HTMLElement>} {...p} size="lg" tooltip={user.name}>
              <Avatar name={user.name} decorative />
              <span className="flex min-w-0 flex-1 flex-col">
                <span className="truncate text-label-medium text-fg-primary">{user.name}</span>
                <span className="truncate text-caption-default">{user.email}</span>
              </span>
              <Icon name={ChevronsUpDown} size={16} />
            </SidebarMenuButton>
          )}
        />
      </SidebarMenuItem>
    </SidebarMenu>
  );
}

"use client";
import type { ReactNode } from "react";
import { Breadcrumbs } from "@/components/ui/nav-extra";
import { SidebarTrigger } from "@/components/ui/sidebar";

/** The bar above the page: sidebar toggle, breadcrumbs and optional actions on the end side. */
export function SiteHeader({ crumbs, actions }: { crumbs: { label: string; href?: string }[]; actions?: ReactNode }) {
  return (
    <header className="sticky top-0 z-[var(--ds-z-sticky)] flex h-14 shrink-0 items-center gap-2 border-b border-line-default bg-surface px-4 md:rounded-t-[inherit]">
      <SidebarTrigger className="-ms-1" />
      <span aria-hidden className="mx-1 h-4 w-px bg-line-default" />
      <Breadcrumbs items={crumbs} />
      {actions && <div className="ms-auto flex items-center gap-2">{actions}</div>}
    </header>
  );
}

import { Avatar } from "@/components/ui/display";
import { Progress } from "@/components/ui/feedback";

const team = ["Jane Cooper", "Wade Warren", "Esther Howard", "Cameron Williamson", "Brooklyn Simmons"];
const load = [
  { name: "Jane Cooper", tasks: 12, tone: "warning" as const, value: 92 },
  { name: "Wade Warren", tasks: 7, tone: "brand" as const, value: 58 },
  { name: "Esther Howard", tasks: 5, tone: "brand" as const, value: 40 },
];

export function ProjectSummary() {
  return (
    <div className="grid gap-4 md:grid-cols-3">
      <section aria-labelledby="ps-progress" className="flex flex-col gap-3 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)]">
        <h2 id="ps-progress" className="text-heading-h4">Progress</h2>
        <p className="text-heading-h2 tabular-nums">64%</p>
        <Progress value={64} label="Tasks done (82 of 128)" />
        <p className="text-caption-default text-fg-secondary">Due March 14 · 18 weeks left</p>
      </section>
      <section aria-labelledby="ps-team" className="flex flex-col gap-3 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)]">
        <h2 id="ps-team" className="text-heading-h4">Team</h2>
        <ul className="flex -space-x-2">{team.map((n) => <li key={n} className="rounded-full ring-2 ring-[var(--ds-color-bg-surface)]"><Avatar name={n} size="lg" /></li>)}</ul>
        <dl className="grid grid-cols-2 gap-2 text-body-small">
          <dt className="text-fg-secondary">Owner</dt><dd>Jane Cooper</dd>
          <dt className="text-fg-secondary">Client</dt><dd>Acme Inc</dd>
        </dl>
      </section>
      <section aria-labelledby="ps-load" className="flex flex-col gap-3 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)]">
        <h2 id="ps-load" className="text-heading-h4">Workload</h2>
        <ul className="flex flex-col gap-3">{load.map((l) => <li key={l.name}><Progress value={l.value} tone={l.tone} label={`${l.name} · ${l.tasks} open tasks`} /></li>)}</ul>
      </section>
    </div>
  );
}

import { Stepper } from "@/components/ui/navigation";

export function Milestones() {
  return (
    <section aria-labelledby="ms-title" className="flex flex-col gap-4 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)] lg:col-span-3">
      <h2 id="ms-title" className="text-heading-h4">Milestones</h2>
      <Stepper steps={[
        { label: "Discovery", description: "Done Nov 2", status: "complete" },
        { label: "Content model", description: "Done Nov 20", status: "complete" },
        { label: "Templates", description: "Due Jan 15", status: "current" },
        { label: "Launch", description: "Mar 14", status: "upcoming" },
      ]} />
    </section>
  );
}

import { Avatar } from "@/components/ui/display";

const items = [
  { who: "Wade Warren", what: "moved “Pricing page” to Review", when: "12 min ago" },
  { who: "Esther Howard", what: "commented on “Hero copy”", when: "1 h ago" },
  { who: "Jane Cooper", what: "completed “Navigation spec”", when: "3 h ago" },
  { who: "Brooklyn Simmons", what: "uploaded 14 photos to Assets", when: "Yesterday" },
];

export function Activity() {
  return (
    <section aria-labelledby="act-title" className="flex flex-col gap-4 rounded-container border border-line-default bg-surface p-[var(--ds-padding-card)] lg:col-span-2">
      <h2 id="act-title" className="text-heading-h4">Recent activity</h2>
      <ol className="flex flex-col gap-4">
        {items.map((i) => (
          <li key={i.what} className="flex gap-3">
            <Avatar name={i.who} decorative />
            <p className="flex min-w-0 flex-1 flex-col text-body-small"><span><span className="text-label-medium">{i.who}</span> {i.what}</span><span className="text-caption-default text-fg-secondary">{i.when}</span></p>
          </li>
        ))}
      </ol>
    </section>
  );
}
